14	export function parsePyFloat(str) {
15	  const s = String(str).trim();
16	  const m = /^([+-]?)(inf(inity)?|nan)$/i.exec(s);
17	  if (m) {
18	    if (m[2].toLowerCase() === 'nan') return NaN;
19	    return m[1] === '-' ? -Infinity : Infinity;
20	  }
21	  if (!FLOAT_RE.test(s)) throw new FloatParseError(str);
22	  return Number(s.replace(/_/g, ''));
23	}
