25	export function pyFloatRepr(x) {
26	  if (Number.isNaN(x)) return 'nan';
27	  if (x === Infinity) return 'inf';
28	  if (x === -Infinity) return '-inf';
29	  const neg = x < 0 || Object.is(x, -0);
30	  const a = Math.abs(x);
31	  let out;
32	  if (a === 0) {
33	    out = '0.0';
34	  } else {
35	    // Shortest round-trip digits via toExponential() with no argument.
36	    const s = a.toExponential(); // e.g. '1.2345678912345679e+8'
37	    const eIdx = s.indexOf('e');
38	    const digits = s.slice(0, eIdx).replace('.', '');
39	    const e = parseInt(s.slice(eIdx + 1), 10);
40	    const decpt = e + 1;
41	    if (decpt <= -4 || decpt > 16) {
42	      let body = digits[0];
43	      if (digits.length > 1) body += '.' + digits.slice(1);
44	      const exp = decpt - 1;
45	      const sign = exp < 0 ? '-' : '+';
46	      const absExp = String(Math.abs(exp)).padStart(2, '0');
47	      out = body + 'e' + sign + absExp;
48	    } else if (decpt <= 0) {
49	      out = '0.' + '0'.repeat(-decpt) + digits;
50	    } else if (decpt >= digits.length) {
51	      out = digits + '0'.repeat(decpt - digits.length) + '.0';
52	    } else {
53	      out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
54	    }
55	  }
56	  return neg ? '-' + out : out;
57	}

