// Mirrors: argparse --a (float, required) -> canonicaljson.encode_canonical_json
// -> print of the resulting bytes object (e.g. b'-3.14159').

import { basename } from 'node:path';
import { parseArgs } from './argparse.mjs';
import { encodeCanonicalJson } from './canonicaljson.mjs';
import { pyBytesRepr } from './pybytes.mjs';

function main() {
  // argparse derives prog from basename(sys.argv[0]); here argv[1] is the script.
  const prog = basename(process.argv[1]);
  const { a } = parseArgs(process.argv.slice(2), prog);

  let result;
  try {
    result = encodeCanonicalJson(a);
  } catch (err) {
    // Python dies with an uncaught ValueError (exit code 1). The full
    // traceback cannot be reproduced; replicate the observable contract.
    process.stderr.write(`ValueError: ${err.message}\n`);
    process.exit(1);
  }

  console.log(pyBytesRepr(result));
}

main();

